            "recoveryFilesTitle": "ไฟล์การกู้คืนย้ายออกจากบันทึก",
            "recoveryFilesDescription": "ไฟล์ Snapshots และ Gossamer Archive ที่ใช้กู้คืนข้อมูลโน้ตที่ถูกลบหรือเขียนทับ ตอนนี้อยู่ใน Radial Timeline/Recover แทน Radial Timeline/Logs โฟลเดอร์ Logs มีเฉพาะบันทึกการทำงานที่ลบทิ้งได้ จึงสามารถล้างได้โดยไม่สูญเสียข้อมูลกู้คืน หากยังมีโฟลเดอร์จากก่อนการอัปเดตนี้อยู่ที่ Radial Timeline/Logs/Snapshots หรือ Radial Timeline/Logs/Gossamer Archive ให้ย้ายเฉพาะโฟลเดอร์นั้นไปที่ Radial Timeline/Recover เพื่อเก็บข้อมูลกู้คืนเดิม คำเตือน: ห้ามย้าย Radial Timeline/Snapshots เพราะเป็นอีกโฟลเดอร์หนึ่งที่ Timeline Repair ยังใช้อ่านข้อมูลเพื่อกู้คืนไทม์ไลน์ การย้ายโฟลเดอร์นี้จะทำให้การกู้คืนดังกล่าวใช้งานไม่ได้",
